// Generates TypeScript types for the `public` schema of the local database.
// `--check` fails instead of writing when the committed file is out of date.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { format, resolveConfig } from "prettier";
import { runSupabase } from "./run-supabase.mjs";

const target = fileURLToPath(
  new URL("../packages/core/src/db/database.types.ts", import.meta.url),
);
const header =
  "// Generated by `pnpm db:types` from the local Supabase database. Do not edit.\n\n";

const generated = runSupabase([
  "gen",
  "types",
  "--lang",
  "typescript",
  "--schema",
  "public",
]);
const formatted = await format(header + generated, {
  ...(await resolveConfig(target)),
  filepath: target,
});

if (process.argv.includes("--check")) {
  const committed = await readFile(target, "utf8").catch(() => "");
  if (committed !== formatted) {
    console.error(
      "packages/core/src/db/database.types.ts is out of date. Run `pnpm db:types` and commit the result.",
    );
    process.exit(1);
  }
  console.log("Database types are up to date.");
} else {
  await writeFile(target, formatted);
  console.log("Wrote packages/core/src/db/database.types.ts");
}
